"""Build T001 audit registry from Crossref responses and manually inspected source locators.
No digitization, fitting, or capacity reconstruction is performed.
"""
import json,re,hashlib,csv,html,platform
from pathlib import Path
import yaml
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[2]
DATE='2026-11-16'
R=[]
def clean(s): return re.sub(r'\s+',' ',html.unescape(BeautifulSoup(s,'html.parser').get_text() if '<' in s else s)).strip()
def cond(T='unknown',p='unknown',rh='unknown',gas='unknown',pei='not applicable',mw='not applicable',activation='unknown',locator='unknown'):
 return dict(temperature=T,pressure_or_p_CO2=p,RH=rh,gas_composition=gas,PEI_loading=pei,PEI_Mw=mw,activation=activation,methods_locator=locator)
def item(what,where,typ='figure_only',conditions='same as source conditions',norm='mmol/g dry adsorbent',basis='experimental'):
 return dict(what=what,where=where,data_type=typ,conditions=conditions,normalization=norm,evidence_kind=basis)
def add(sid,materials,conditions,items,role,limits,license='unknown',oa=None,files=None,access='full_text',links=None,unlocated=None):
 p=ROOT/'sources/metadata'/f'{sid}.crossref.json'
 m=json.loads(p.read_text())['message']
 authors=[clean(a.get('given','')+' '+a.get('family',a.get('name',''))) for a in m.get('author',[])[:3]]
 if len(m.get('author',[]))>3:authors.append('et al.')
 doi=m['DOI']
 row=dict(source_id=sid,doi=doi,doi_verified=True,url='https://doi.org/'+doi,oa_url=oa,title=clean(m['title'][0]),authors=authors,year=m['published']['date-parts'][0][0],journal=clean(m.get('container-title',['SSRN preprint'])[0]) if m.get('container-title') else 'SSRN preprint',license=license,accessed=DATE,files_available=files or [],materials=materials,conditions=conditions,data_items=items,role_candidate=role,limitations=limits,status='provisional',access_level=access,doi_evidence=str(p.relative_to(ROOT)),doi_verification_scope='Crossref DOI, title, first authors, publication year and container checked; not independent data verification',evidence_urls=links or [oa or 'https://doi.org/'+doi],unlocated_data=unlocated or [])
 for i,x in enumerate(items,1):x['extraction_id']=f'T001-{sid}-{i:02d}';x['status']='provisional'
 row['extraction_id']=f'T001-{sid}-audit'
 row['acceptance_core_measured_UiO_CO2']=sid in ['S2','S100','S103','S104','S105','S113']
 R.append(row)
R.append(dict(source_id='S1',doi=None,doi_verified=False,url='https://ug.edu.pl/news/pl/10481/innowacyjna-technologia-wychwytu-co2-grant-dla-wydzialu-chemii',oa_url=None,title='Innowacyjna technologia wychwytu CO₂ - grant dla Wydziału Chemii',authors=['Wydział Chemii UG; oprac. KŻW/CKiP'],year=2026,journal='Aktualności — Uniwersytet Gdański',license='unknown; public news page, no reuse licence located',accessed=DATE,files_available=['Public HTML news, dated 2026-06-18; read, not downloaded'],materials=['Planned PET-derived porous coordination polymer; exact framework unknown'],conditions=cond(),data_items=[],role_candidate='context',limitations=['Grant announcement, no experimental adsorption data, figures or tables of capacity.','Does not specify UiO-66/PEI or establish collaboration with this project.'],status='provisional',extraction_id='T001-S1-audit',acceptance_core_measured_UiO_CO2=False))
